from typing import List, Tuple

def divide_interval(l: int, r: int) -> Tuple[int, List[Tuple[int, int]]]:
    lis = []
    while l < r:
        i = 0
        while l % pow(2, i+1) == 0 and l + pow(2, i+1) <= r:
            i += 1
        lis.append((l, l + pow(2, i)))
        l += pow(2, i)
    return len(lis), lis
